6	// PadV3GradReplication AscendC kernel — replication padding backward (4D + 5D)
7	// Key design: each padded row contributes interior + left/right pad to one output row.
8	// All data segments are loaded directly from GM at the correct offset — *no*
9	// DataCopyParams srcStride tricks that rely on stride-as-offset semantics.
10	
11	#include "kernel_operator.h"
12	
13	constexpr int32_t BUFFER_NUM = 2;
14	
15	// ---------------------------------------------------------------------------
16	// Helper: load from GM into UB via DataCopyPad
17	// ---------------------------------------------------------------------------
18	template <typename T>
19	__aicore__ inline void GmLoadUb(
20	    AscendC::LocalTensor<T> &dst, AscendC::GlobalTensor<T> src, uint32_t count)
21	{
22	    AscendC::DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
23	    AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
24	    AscendC::DataCopyPad(dst, src, cp, pp);
25	}
26	
27	template <typename T>
28	__aicore__ inline void UbStoreGm(
29	    AscendC::GlobalTensor<T> dst, AscendC::LocalTensor<T> &src, uint32_t count)
30	{
31	    AscendC::DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
32	    AscendC::DataCopyPad(dst, src, cp);
33	}
34	
35	// =============================== 4D Kernel ================================
36	template <typename dataType>
37	class PadV3Grad4DKernel {
38	public:
39	    __aicore__ inline void Init(GM_ADDR go, GM_ADDR gi,
40	        int32_t tnc, int32_t H, int32_t W, int32_t oH, int32_t oW,
41	        int32_t pt, int32_t pb, int32_t pl, int32_t pr, int32_t bn, int32_t npb)
42	    {
43	        totalNc=tnc; this->H=H; this->W=W; outH=oH; outW=oW;
44	        this->pt=pt; this->pb=pb; this->pl=pl; this->pr=pr;
45	        ncPerBlock=npb; blockNum=bn;
46	        goGM_.SetGlobalBuffer((__gm__ dataType*)go,(uint64_t)totalNc*outH*outW);
47	        giGM_.SetGlobalBuffer((__gm__ dataType*)gi,(uint64_t)totalNc*H*W);
48	        if ASCEND_IS_AIV InitBufs();
49	    }
50	    __aicore__ inline void Process() {
51	        if ASCEND_IS_AIV {
52	            int ci=AscendC::GetBlockIdx();
53	            for (int li=0;li<ncPerBlock;++li) {
54	                int nc=ci*ncPerBlock+li;
55	                if (nc>=totalNc) break;
56	                RunNc(nc);
57	            }
58	        }
59	    }
60	private:
61	    __aicore__ inline void InitBufs() {
62	        pipe.InitBuffer(giQ_,BUFFER_NUM,W*sizeof(dataType));
63	        // goQ_ must hold the largest segment: max(W, pl, pr) = max(W, outW) = outW
64	        pipe.InitBuffer(goQ_,BUFFER_NUM,outW*sizeof(dataType));
65	        pipe.InitBuffer(giOQ_,BUFFER_NUM,W*sizeof(dataType));
66	        pipe.InitBuffer(goFB_,outW*sizeof(float));
67	        pipe.InitBuffer(accB_,W*sizeof(float));
68	        // tmpB_: holds one row-segment (f32), up to outW
69	        pipe.InitBuffer(tmpB_,outW*sizeof(float));
70	        pipe.InitBuffer(sumB_,16*sizeof(float));
71	        pipe.InitBuffer(rdcB_,(uint32_t)outW*sizeof(float));
72	    }
73	    __aicore__ inline uint64_t goOff(uint64_t nc,int32_t oh)
74	        {return nc*(uint64_t)outH*outW+(uint64_t)oh*outW;}
75	    __aicore__ inline uint64_t giOff(uint64_t nc,int32_t h)
76	        {return nc*(uint64_t)H*W+(uint64_t)h*W;}
77	
78	    // ----- Input / Output helpers -----
79	    __aicore__ inline void CopyInGi(uint64_t nc,int32_t h) {
80	        giT_=giQ_.AllocTensor<dataType>();
81	        GmLoadUb(giT_,giGM_[giOff(nc,h)],(uint32_t)W);
82	        giQ_.EnQue(giT_);
83	    }
84	    __aicore__ inline void CopyOutGi(uint64_t nc,int32_t h) {
85	        giOT_=giOQ_.DeQue<dataType>();
86	        UbStoreGm(giGM_[giOff(nc,h)],giOT_,(uint32_t)W);
87	        giOQ_.FreeTensor(giOT_);
88	    }
89	
90	    // ----- Accumulator management -----
91	    __aicore__ inline void ZeroAcc() {
92	        acc_=accB_.Get<float>();
93	        // Load gi (zeros from host-init'd output) just to feed the pipeline,
94	        // then Duplicate to guarantee zero acc_.
95	        giT_=giQ_.DeQue<dataType>();
96	        if constexpr (std::is_same_v<dataType,float>) {
97	            AscendC::DataCopyParams cp{1,(uint16_t)W,0,0};
98	            AscendC::DataCopy(acc_,giT_,cp);
99	        } else {
100	            AscendC::Cast(acc_,giT_,AscendC::RoundMode::CAST_NONE,W);
101	            AscendC::PipeBarrier<PIPE_V>();
102	        }
103	        AscendC::Duplicate(acc_,0.0f,W);
104	        giQ_.FreeTensor(giT_);
105	        AscendC::PipeBarrier<PIPE_ALL>();
106	    }
107	    __aicore__ inline void FlushAcc() {
108	        giOT_=giOQ_.AllocTensor<dataType>();
109	        if constexpr (!std::is_same_v<dataType,float>) {
110	            AscendC::Cast(giOT_,acc_,AscendC::RoundMode::CAST_NONE,W);
111	        } else {
112	            AscendC::DataCopyParams cp{1,(uint16_t)W,0,0};
113	            AscendC::DataCopy(giOT_,acc_,cp);
114	        }
115	        AscendC::PipeBarrier<PIPE_V>();
116	        giOQ_.EnQue(giOT_);
117	    }
118	
119	    // ----- Convert loaded goT_ (dataType) → goF32_ (float) -----
120	    __aicore__ inline void PrepGoF32(int32_t count) {
121	        if constexpr (std::is_same_v<dataType,float>) {
122	            goF32_=goT_.template ReinterpretCast<float>();
123	        } else {
124	            goF32_=goFB_.Get<float>();
125	            AscendC::Cast(goF32_,goT_,AscendC::RoundMode::CAST_NONE,count);
126	            AscendC::PipeBarrier<PIPE_V>();
127	        }
128	    }
129	
130	    // ----- Core accumulation: each segment loaded directly from GM offset -----
131	
132	    /// Load INTERIOR segment go[nc,oh][pl : pl+W] and add to acc_[0:W].
133	    __aicore__ inline void AccInterior(uint64_t nc,int32_t oh) {
134	        goT_=goQ_.AllocTensor<dataType>();
135	        GmLoadUb(goT_,goGM_[goOff(nc,oh)+pl],(uint32_t)W);
136	        goQ_.EnQue(goT_);
137	        goT_=goQ_.DeQue<dataType>();
138	        PrepGoF32(W);
139	        AscendC::PipeBarrier<PIPE_ALL>();
140	        AscendC::Add(acc_,acc_,goF32_,W);
141	        goQ_.FreeTensor(goT_);
142	        AscendC::PipeBarrier<PIPE_ALL>();
143	    }
144	
145	    /// Load LEFT-PAD segment go[nc,oh][0 : pl], reduce-sum, add to acc_[0].
146	    __aicore__ inline void AccLeftPad(uint64_t nc,int32_t oh) {
147	        if (pl<=0) return;
148	        goT_=goQ_.AllocTensor<dataType>();
149	        GmLoadUb(goT_,goGM_[goOff(nc,oh)],(uint32_t)pl);
150	        goQ_.EnQue(goT_);
151	        goT_=goQ_.DeQue<dataType>();
152	        PrepGoF32(pl);
153	        AscendC::PipeBarrier<PIPE_ALL>();
154	        AscendC::LocalTensor<float> s=sumB_.Get<float>();
155	        AscendC::LocalTensor<float> r=rdcB_.Get<float>();
156	        AscendC::ReduceSum<float>(s,goF32_,r,pl);
157	        AscendC::PipeBarrier<PIPE_V>();
158	        float v=s.GetValue(0);
159	        AscendC::PipeBarrier<PIPE_ALL>();
160	        float cur=acc_.GetValue(0);
161	        acc_.SetValue(0,cur+v);
162	        goQ_.FreeTensor(goT_);
163	        AscendC::PipeBarrier<PIPE_ALL>();
164	    }
165	
166	    /// Load RIGHT-PAD segment go[nc,oh][pl+W : outW], reduce-sum, add to acc_[W-1].
167	    __aicore__ inline void AccRightPad(uint64_t nc,int32_t oh) {
168	        if (pr<=0) return;
169	        goT_=goQ_.AllocTensor<dataType>();
170	        GmLoadUb(goT_,goGM_[goOff(nc,oh)+pl+W],(uint32_t)pr);
171	        goQ_.EnQue(goT_);
172	        goT_=goQ_.DeQue<dataType>();
173	        PrepGoF32(pr);
174	        AscendC::PipeBarrier<PIPE_ALL>();
175	        AscendC::LocalTensor<float> s=sumB_.Get<float>();
176	        AscendC::LocalTensor<float> r=rdcB_.Get<float>();
177	        AscendC::ReduceSum<float>(s,goF32_,r,pr);
178	        AscendC::PipeBarrier<PIPE_V>();
179	        float v=s.GetValue(0);
180	        AscendC::PipeBarrier<PIPE_ALL>();
181	        float cur=acc_.GetValue(W-1);
182	        acc_.SetValue(W-1,cur+v);
183	        goQ_.FreeTensor(goT_);
184	        AscendC::PipeBarrier<PIPE_ALL>();
185	    }
186	
187	    // ----- Process one output row -----
188	    __aicore__ inline void ProcRow(uint64_t nc,int32_t h,int32_t ohS,int32_t ohE) {
189	        CopyInGi(nc,h);
190	        ZeroAcc();
191	        // Accumulate contributions from every padded row that maps to this output row
192	        for (int oh=ohS;oh<=ohE;++oh) {
193	            AccInterior(nc,oh);
194	            AccLeftPad(nc,oh);
195	            AccRightPad(nc,oh);
196	        }
197	        FlushAcc();
198	        CopyOutGi(nc,h);
199	    }
200	
201	    __aicore__ inline void RunNc(int32_t nc) {
202	        uint64_t n64=(uint64_t)nc;
203	        for (int h=0;h<H;++h) {
204	            int ohS,ohE;
205	            if (h==0)      { ohS=0;         ohE=pt;          }
206	            else if (h==H-1){ ohS=pt+H-1;    ohE=outH-1;      }
207	            else           { ohS=pt+h;       ohE=pt+h;        }
208	            ProcRow(n64,h,ohS,ohE);
209	        }
210	    }
211	
212	private:
213	    int32_t totalNc=0,H=0,W=0,outH=0,outW=0,pt=0,pb=0,pl=0,pr=0,ncPerBlock=0,blockNum=0;
214	    AscendC::TPipe pipe;
215	    AscendC::GlobalTensor<dataType> goGM_,giGM_;
216	    AscendC::TQue<AscendC::TPosition::VECIN,BUFFER_NUM> giQ_,goQ_;
217	    AscendC::TQue<AscendC::TPosition::VECOUT,BUFFER_NUM> giOQ_;
218	    AscendC::TBuf<AscendC::TPosition::VECCALC> goFB_,accB_,tmpB_,sumB_,rdcB_;
219	    AscendC::LocalTensor<dataType> giT_,goT_,giOT_;
220	    AscendC::LocalTensor<float> acc_,goF32_;
221	};
222	
223	// =============================== 5D Kernel ================================
224	template <typename dataType>
225	class PadV3Grad5DKernel {
226	public:
227	    __aicore__ inline void Init(GM_ADDR go, GM_ADDR gi,
228	        int32_t tnc,int32_t D,int32_t H,int32_t W,
229	        int32_t oD,int32_t oH,int32_t oW,
230	        int32_t dl,int32_t dr,int32_t hl,int32_t hr,int32_t wl,int32_t wr,
231	        int32_t bn,int32_t npb)
232	    {
233	        totalNc=tnc; this->D=D; this->H=H; this->W=W; outD=oD; outH=oH; outW=oW;
234	        this->dl=dl; this->dr=dr; this->hl=hl; this->hr=hr; this->wl=wl; this->wr=wr;
235	        ncPerBlock=npb; blockNum=bn;
236	        goGM_.SetGlobalBuffer((__gm__ dataType*)go,(uint64_t)totalNc*outD*outH*outW);
237	        giGM_.SetGlobalBuffer((__gm__ dataType*)gi,(uint64_t)totalNc*D*H*W);
238	        if ASCEND_IS_AIV InitBufs();
239	    }
240	    __aicore__ inline void Process() {
241	        if ASCEND_IS_AIV {
242	            int ci=AscendC::GetBlockIdx();
243	            for (int li=0;li<ncPerBlock;++li) {
244	                int nc=ci*ncPerBlock+li;
245	                if (nc>=totalNc) break;
246	                RunNc(nc);
247	            }
248	        }
249	    }
250	private:
251	    __aicore__ inline void InitBufs() {
252	        pipe.InitBuffer(giQ_,BUFFER_NUM,W*sizeof(dataType));
253	        pipe.InitBuffer(goQ_,BUFFER_NUM,outW*sizeof(dataType));
254	        pipe.InitBuffer(giOQ_,BUFFER_NUM,W*sizeof(dataType));
255	        pipe.InitBuffer(goFB_,outW*sizeof(float));
256	        pipe.InitBuffer(accB_,W*sizeof(float));
257	        pipe.InitBuffer(tmpB_,outW*sizeof(float));
258	        pipe.InitBuffer(sumB_,16*sizeof(float));
259	        pipe.InitBuffer(rdcB_,(uint32_t)outW*sizeof(float));
260	    }
261	    __aicore__ inline uint64_t goOff(uint64_t nc,int32_t pd,int32_t ph) {
262	        return nc*(uint64_t)outD*outH*outW+(uint64_t)pd*outH*outW+(uint64_t)ph*outW;
263	    }
264	    __aicore__ inline uint64_t giOff(uint64_t nc,int32_t d,int32_t h) {
265	        return nc*(uint64_t)D*H*W+(uint64_t)d*H*W+(uint64_t)h*W;
266	    }
267	    __aicore__ inline void CopyInGi(uint64_t nc,int32_t d,int32_t h) {
268	        giT_=giQ_.AllocTensor<dataType>();
269	        GmLoadUb(giT_,giGM_[giOff(nc,d,h)],(uint32_t)W);
270	        giQ_.EnQue(giT_);
271	    }
272	    __aicore__ inline void CopyOutGi(uint64_t nc,int32_t d,int32_t h) {
273	        giOT_=giOQ_.DeQue<dataType>();
274	        UbStoreGm(giGM_[giOff(nc,d,h)],giOT_,(uint32_t)W);
275	        giOQ_.FreeTensor(giOT_);
276	    }
277	    __aicore__ inline void ZeroAcc() {
278	        acc_=accB_.Get<float>();
279	        giT_=giQ_.DeQue<dataType>();
280	        if constexpr (std::is_same_v<dataType,float>) {
281	            AscendC::DataCopyParams cp{1,(uint16_t)W,0,0};
282	            AscendC::DataCopy(acc_,giT_,cp);
283	        } else {
284	            AscendC::Cast(acc_,giT_,AscendC::RoundMode::CAST_NONE,W);
285	            AscendC::PipeBarrier<PIPE_V>();
286	        }
287	        AscendC::Duplicate(acc_,0.0f,W);
288	        giQ_.FreeTensor(giT_);
289	        AscendC::PipeBarrier<PIPE_ALL>();
290	    }
291	    __aicore__ inline void FlushAcc() {
292	        giOT_=giOQ_.AllocTensor<dataType>();
293	        if constexpr (!std::is_same_v<dataType,float>) {
294	            AscendC::Cast(giOT_,acc_,AscendC::RoundMode::CAST_NONE,W);
295	        } else {
296	            AscendC::DataCopyParams cp{1,(uint16_t)W,0,0};
297	            AscendC::DataCopy(giOT_,acc_,cp);
298	        }
299	        AscendC::PipeBarrier<PIPE_V>();
300	        giOQ_.EnQue(giOT_);
301	    }
302	    __aicore__ inline void PrepGoF32(int32_t count) {
303	        if constexpr (std::is_same_v<dataType,float>) {
304	            goF32_=goT_.template ReinterpretCast<float>();
305	        } else {
306	            goF32_=goFB_.Get<float>();
307	            AscendC::Cast(goF32_,goT_,AscendC::RoundMode::CAST_NONE,count);
308	            AscendC::PipeBarrier<PIPE_V>();
309	        }
310	    }
311	    __aicore__ inline void AccInterior(uint64_t nc,int32_t pd,int32_t ph) {
312	        goT_=goQ_.AllocTensor<dataType>();
313	        GmLoadUb(goT_,goGM_[goOff(nc,pd,ph)+wl],(uint32_t)W);
314	        goQ_.EnQue(goT_);
315	        goT_=goQ_.DeQue<dataType>();
316	        PrepGoF32(W);
317	        AscendC::PipeBarrier<PIPE_ALL>();
318	        AscendC::Add(acc_,acc_,goF32_,W);
319	        goQ_.FreeTensor(goT_);
320	        AscendC::PipeBarrier<PIPE_ALL>();
321	    }
322	    __aicore__ inline void AccLeftPad(uint64_t nc,int32_t pd,int32_t ph) {
323	        if (wl<=0) return;
324	        goT_=goQ_.AllocTensor<dataType>();
325	        GmLoadUb(goT_,goGM_[goOff(nc,pd,ph)],(uint32_t)wl);
326	        goQ_.EnQue(goT_);
327	        goT_=goQ_.DeQue<dataType>();
328	        PrepGoF32(wl);
329	        AscendC::PipeBarrier<PIPE_ALL>();
330	        AscendC::LocalTensor<float> s=sumB_.Get<float>();
331	        AscendC::LocalTensor<float> r=rdcB_.Get<float>();
332	        AscendC::ReduceSum<float>(s,goF32_,r,wl);
333	        AscendC::PipeBarrier<PIPE_V>();
334	        float v=s.GetValue(0);
335	        AscendC::PipeBarrier<PIPE_ALL>();
336	        float cur=acc_.GetValue(0);
337	        acc_.SetValue(0,cur+v);
338	        goQ_.FreeTensor(goT_);
339	        AscendC::PipeBarrier<PIPE_ALL>();
340	    }
341	    __aicore__ inline void AccRightPad(uint64_t nc,int32_t pd,int32_t ph) {
342	        if (wr<=0) return;
343	        goT_=goQ_.AllocTensor<dataType>();
344	        GmLoadUb(goT_,goGM_[goOff(nc,pd,ph)+wl+W],(uint32_t)wr);
345	        goQ_.EnQue(goT_);
346	        goT_=goQ_.DeQue<dataType>();
347	        PrepGoF32(wr);
348	        AscendC::PipeBarrier<PIPE_ALL>();
349	        AscendC::LocalTensor<float> s=sumB_.Get<float>();
350	        AscendC::LocalTensor<float> r=rdcB_.Get<float>();
351	        AscendC::ReduceSum<float>(s,goF32_,r,wr);
352	        AscendC::PipeBarrier<PIPE_V>();
353	        float v=s.GetValue(0);
354	        AscendC::PipeBarrier<PIPE_ALL>();
355	        float cur=acc_.GetValue(W-1);
356	        acc_.SetValue(W-1,cur+v);
357	        goQ_.FreeTensor(goT_);
358	        AscendC::PipeBarrier<PIPE_ALL>();
359	    }
360	    __aicore__ inline void ProcSlice(uint64_t nc,int32_t d,int32_t h,
361	        int32_t pdS,int32_t pdE,int32_t phS,int32_t phE) {
362	        CopyInGi(nc,d,h);
363	        ZeroAcc();
364	        for(int pd=pdS;pd<=pdE;++pd)
365	            for(int ph=phS;ph<=phE;++ph) {
366	                AccInterior(nc,pd,ph);
367	                AccLeftPad(nc,pd,ph);
368	                AccRightPad(nc,pd,ph);
369	            }
370	        FlushAcc();
371	        CopyOutGi(nc,d,h);
372	    }
373	    __aicore__ inline void RunNc(int32_t nc) {
374	        uint64_t n64=(uint64_t)nc;
375	        for(int d=0;d<D;++d) {
376	            int pdS,pdE;
377	            if(d==0)      { pdS=0;         pdE=dl;          }
378	            else if(d==D-1){ pdS=dl+D-1;    pdE=outD-1;      }
379	            else          { pdS=dl+d;       pdE=dl+d;        }
380	            for(int h=0;h<H;++h) {
381	                int phS,phE;
382	                if(h==0)      { phS=0;         phE=hl;          }
383	                else if(h==H-1){ phS=hl+H-1;    phE=outH-1;      }
384	                else          { phS=hl+h;       phE=hl+h;        }
385	                ProcSlice(n64,d,h,pdS,pdE,phS,phE);
386	            }
387	        }
388	    }
389	private:
390	    int32_t totalNc=0,D=0,H=0,W=0,outD=0,outH=0,outW=0;
391	    int32_t dl=0,dr=0,hl=0,hr=0,wl=0,wr=0;
392	    int32_t ncPerBlock=0,blockNum=0;
393	    AscendC::TPipe pipe;
394	    AscendC::GlobalTensor<dataType> goGM_,giGM_;
395	    AscendC::TQue<AscendC::TPosition::VECIN,BUFFER_NUM> giQ_,goQ_;
396	    AscendC::TQue<AscendC::TPosition::VECOUT,BUFFER_NUM> giOQ_;
397	    AscendC::TBuf<AscendC::TPosition::VECCALC> goFB_,accB_,tmpB_,sumB_,rdcB_;
398	    AscendC::LocalTensor<dataType> giT_,goT_,giOT_;
399	    AscendC::LocalTensor<float> acc_,goF32_;
400	};
401	
402	// =============================== Entry =====================================
403	extern "C" __global__ __aicore__ void pad_v3_grad_replication_4d(
404	    GM_ADDR go,GM_ADDR gi,int32_t tnc,int32_t H,int32_t W,int32_t oH,int32_t oW,
405	    int32_t pt,int32_t pb,int32_t pl,int32_t pr,int32_t bn,int32_t npb,int64_t df)
406	{if(df==0){PadV3Grad4DKernel<float> k;k.Init(go,gi,tnc,H,W,oH,oW,pt,pb,pl,pr,bn,npb);k.Process();}
407	 else if(df==1){PadV3Grad4DKernel<half> k;k.Init(go,gi,tnc,H,W,oH,oW,pt,pb,pl,pr,bn,npb);k.Process();}
408	 else{PadV3Grad4DKernel<bfloat16_t> k;k.Init(go,gi,tnc,H,W,oH,oW,pt,pb,pl,pr,bn,npb);k.Process();}}
409	
410	extern "C" __global__ __aicore__ void pad_v3_grad_replication_5d(
411	    GM_ADDR go,GM_ADDR gi,int32_t tnc,int32_t D,int32_t H,int32_t W,
412	    int32_t oD,int32_t oH,int32_t oW,
413	    int32_t dl,int32_t dr,int32_t hl,int32_t hr,int32_t wl,int32_t wr,
414	    int32_t bn,int32_t npb,int64_t df)
415	{if(df==0){PadV3Grad5DKernel<float> k;k.Init(go,gi,tnc,D,H,W,oD,oH,oW,dl,dr,hl,hr,wl,wr,bn,npb);k.Process();}
416	 else if(df==1){PadV3Grad5DKernel<half> k;k.Init(go,gi,tnc,D,H,W,oD,oH,oW,dl,dr,hl,hr,wl,wr,bn,npb);k.Process();}
417	 else{PadV3Grad5DKernel<bfloat16_t> k;k.Init(go,gi,tnc,D,H,W,oD,oH,oW,dl,dr,hl,hr,wl,wr,bn,npb);k.Process();}}
