// PadV4Grad host-side: tiling + kernel launch

#include <torch/extension.h>
#include <sys/types.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_pad_v4_grad.h"

namespace ascend_kernel {

at::Tensor pad_v4_grad(
    const at::Tensor &grad_output,
    at::IntArrayRef ge_padding)
{
    // -------- 1. Input validation --------
    TORCH_CHECK(grad_output.dim() == 4, "PadV4Grad only supports 4D NCHW");
    TORCH_CHECK(ge_padding.size() == 8, "ge_padding must have 8 elements");

    int32_t pt = static_cast<int32_t>(ge_padding[4]);
    int32_t pb = static_cast<int32_t>(ge_padding[5]);
    int32_t pl = static_cast<int32_t>(ge_padding[6]);
    int32_t pr = static_cast<int32_t>(ge_padding[7]);

    int64_t N = grad_output.size(0);
    int64_t C = grad_output.size(1);
    int64_t oH = grad_output.size(2); // padded height
    int64_t oW = grad_output.size(3); // padded width

    int64_t H = oH - pt - pb; // original height
    int64_t W = oW - pl - pr; // original width

    TORCH_CHECK(H > 0 && W > 0, "Invalid padding: resulting H/W <= 0");

    // -------- 2. Create output tensor --------
    auto grad_input = at::zeros(
        {N, C, H, W},
        grad_output.options()
    );
    grad_input = grad_input.contiguous();

    // -------- 3. Platform info --------
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int32_t coreNum = static_cast<int32_t>(ascendc_platform->GetCoreNumAiv());

    // -------- 4. Tiling --------
    int32_t totalNc = static_cast<int32_t>(N * C);
    int32_t blockNum = coreNum;
    int32_t ncPerBlock = (totalNc + blockNum - 1) / blockNum;

    // -------- 5. Dtype flag --------
    int64_t df = 0; // float32
    if (grad_output.scalar_type() == at::ScalarType::Half) {
        df = 1;
    } else if (grad_output.scalar_type() == at::ScalarType::BFloat16) {
        df = 2;
    }

    int32_t H32 = static_cast<int32_t>(H);
    int32_t W32 = static_cast<int32_t>(W);
    int32_t oH32 = static_cast<int32_t>(oH);
    int32_t oW32 = static_cast<int32_t>(oW);

    // -------- 6. Launch --------
    EXEC_KERNEL_CMD(
        pad_v4_grad, blockNum,
        grad_output, grad_input,
        totalNc, H32, W32, oH32, oW32,
        pt, pb, pl, pr,
        blockNum, ncPerBlock, df
    );

    return grad_input;
}

} // namespace ascend_kernel
