65	    __aicore__ inline void InitBufs() {
66	        pipe.InitBuffer(giQ_, BUFFER_NUM, W * sizeof(dataType));
67	        pipe.InitBuffer(goQ_, BUFFER_NUM, outW * sizeof(dataType));
68	        pipe.InitBuffer(giOQ_, BUFFER_NUM, W * sizeof(dataType));
69	        pipe.InitBuffer(goFB_, outW * sizeof(float));
70	        pipe.InitBuffer(accB_, W * sizeof(float));
71	    }
72	
73	    __aicore__ inline uint64_t goOff(uint64_t nc, int32_t oh) {
74	        return nc * (uint64_t)outH * outW + (uint64_t)oh * outW;
75	    }
76	    __aicore__ inline uint64_t giOff(uint64_t nc, int32_t h) {
77	        return nc * (uint64_t)H * W + (uint64_t)h * W;
78	    }
79	
80	    // ---------- Input / Output helpers ----------
81	    __aicore__ inline void CopyInGi(uint64_t nc, int32_t h) {
82	        giT_ = giQ_.AllocTensor<dataType>();
83	        GmLoadUb(giT_, giGM_[giOff(nc, h)], (uint32_t)W);
84	        giQ_.EnQue(giT_);
85	    }
86	
87	    __aicore__ inline void CopyOutGi(uint64_t nc, int32_t h) {
88	        giOT_ = giOQ_.DeQue<dataType>();
89	        UbStoreGm(giGM_[giOff(nc, h)], giOT_, (uint32_t)W);
90	        giOQ_.FreeTensor(giOT_);
91	    }
