93	    // ---------- Accumulator management ----------
94	    __aicore__ inline void ZeroAcc() {
95	        acc_ = accB_.Get<float>();
96	        // Load gi row (zeros from host-init'd output) and Duplicate to zero
97	        giT_ = giQ_.DeQue<dataType>();
98	        if constexpr (std::is_same_v<dataType, float>) {
99	            AscendC::DataCopyParams cp{1, (uint16_t)W, 0, 0};
100	            AscendC::DataCopy(acc_, giT_, cp);
101	        } else {
102	            AscendC::Cast(acc_, giT_, AscendC::RoundMode::CAST_NONE, W);
103	            AscendC::PipeBarrier<PIPE_V>();
104	        }
105	        AscendC::Duplicate(acc_, 0.0f, W);
106	        giQ_.FreeTensor(giT_);
107	        AscendC::PipeBarrier<PIPE_ALL>();
108	    }
109	
110	    __aicore__ inline void FlushAcc() {
111	        giOT_ = giOQ_.AllocTensor<dataType>();
112	        if constexpr (!std::is_same_v<dataType, float>) {
113	            AscendC::Cast(giOT_, acc_, AscendC::RoundMode::CAST_NONE, W);
114	        } else {
115	            AscendC::DataCopyParams cp{1, (uint16_t)W, 0, 0};
116	            AscendC::DataCopy(giOT_, acc_, cp);
117	        }
118	        AscendC::PipeBarrier<PIPE_V>();
119	        giOQ_.EnQue(giOT_);
120	    }
121	
122	    // ---------- Cast padded row to float32 ----------
123	    __aicore__ inline void PrepGoF32(int32_t count) {
124	        if constexpr (std::is_same_v<dataType, float>) {
125	            goF32_ = goT_.template ReinterpretCast<float>();
126	        } else {
127	            goF32_ = goFB_.Get<float>();
128	            AscendC::Cast(goF32_, goT_, AscendC::RoundMode::CAST_NONE, count);
129	            AscendC::PipeBarrier<PIPE_V>();
130	        }
131	    }
132	
133	    // ---------- Load one padded output row ----------
134	    __aicore__ inline void LoadPaddedRow(uint64_t nc, int32_t oh) {
135	        goT_ = goQ_.AllocTensor<dataType>();
136	        GmLoadUb(goT_, goGM_[goOff(nc, oh)], (uint32_t)outW);
137	        goQ_.EnQue(goT_);
138	        goT_ = goQ_.DeQue<dataType>();
139	        PrepGoF32(outW);
140	        AscendC::PipeBarrier<PIPE_ALL>();
141	    }
142	
143	    // ---------- Free loaded padded row ----------
144	    __aicore__ inline void FreePaddedRow() {
145	        goQ_.FreeTensor(goT_);
146	        AscendC::PipeBarrier<PIPE_ALL>();
147	    }
148	
149	    // ---------- Accumulate one contributing output row ----------
150	    __aicore__ inline void AccRow(uint64_t nc, int32_t oh) {
151	        LoadPaddedRow(nc, oh);
152	
153	        // (a) Interior section: acc[0:W] += padded_row[pl:pl+W] (vector add)
154	        AscendC::Add(acc_, acc_, goF32_[pl], W);
155	        AscendC::PipeBarrier<PIPE_ALL>();
156	
157	        // (b) Left reflection: reversed left-padding [ow=0..pl-1]
158	        //   Reflect rule: ow = pl - 1 - w_in  for w_in in [0, pl)
159	        //   Each input column w_in accumulates grad from output column ow
160	        if (pl > 0) {
161	            for (int w_in = 0; w_in < pl && w_in < W; ++w_in) {
162	                int ow = pl - 1 - w_in;
163	                float val = goF32_.GetValue(ow);
164	                float cur = acc_.GetValue(w_in);
165	                acc_.SetValue(w_in, cur + val);
166	            }
167	            AscendC::PipeBarrier<PIPE_ALL>();
168	        }
169	
170	        // (c) Right reflection: reversed right-padding [pl+W..outW-1]
171	        //   Reflect rule: ow = 2*W + pl - 1 - w_in  for w_in in [W-pr, W)
172	        if (pr > 0) {
173	            for (int w_in = W - pr; w_in < W && w_in >= 0; ++w_in) {
174	                int ow = 2 * W + pl - 1 - w_in;
175	                float val = goF32_.GetValue(ow);
176	                float cur = acc_.GetValue(w_in);
177	                acc_.SetValue(w_in, cur + val);
178	            }
179	            AscendC::PipeBarrier<PIPE_ALL>();
180	        }
181	
182	        FreePaddedRow();
183	    }
184	
185	    // ---------- Process one input row ----------
186	    __aicore__ inline void ProcRow(uint64_t nc, int32_t h) {
187	        CopyInGi(nc, h);
188	        ZeroAcc();
189	
190	        // Direct contribution: output row oh = h + pt
191	        AccRow(nc, h + pt);
192	
193	        // Top reflection: input rows h in [0, pt) receive gradient from
194	        //   padded output row oh = pt - h - 1 (reflect rule)
195	        if (h < pt) {
196	            AccRow(nc, pt - h - 1);
197	        }
198	
199	        // Bottom reflection: input rows h in [H-pb, H) receive gradient from
200	        //   padded output row oh = 2*H + pt - h - 1 (reflect rule)
201	        if (h >= H - pb) {
202	            AccRow(nc, 2 * H + pt - h - 1);
203	        }
204	
205	        FlushAcc();
206	        CopyOutGi(nc, h);
207	    }
208	
209	    __aicore__ inline void RunNc(int32_t nc) {
210	        uint64_t n64 = (uint64_t)nc;
211	        for (int h = 0; h < H; ++h) {
212	            ProcRow(n64, h);
213	        }
