 */

// PadV4Grad AscendC kernel — reflect padding backward (4D NCHW)
// Key design: for each input (n,c) pair and each input row h,
// accumulate contributions from up to 3 output rows (direct + top/bottom reflect).
// Each output row contributes interior + reflected edges.
// Sections are loaded directly from GM at the correct offset.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// ---------------------------------------------------------------------------
// Helper: load GM->UB via DataCopyPad
// ---------------------------------------------------------------------------
template <typename T>
__aicore__ inline void GmLoadUb(
    AscendC::LocalTensor<T> &dst, AscendC::GlobalTensor<T> src, uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, cp, pp);
}

template <typename T>
__aicore__ inline void UbStoreGm(
    AscendC::GlobalTensor<T> dst, AscendC::LocalTensor<T> &src, uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, cp);
}

// ============================================================================
template <typename dataType>
class PadV4GradKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR go, GM_ADDR gi,
        int32_t tnc, int32_t H, int32_t W, int32_t oH, int32_t oW,
        int32_t pt, int32_t pb, int32_t pl, int32_t pr,
        int32_t bn, int32_t npb)
    {
        totalNc = tnc; this->H = H; this->W = W; outH = oH; outW = oW;
        this->pt = pt; this->pb = pb; this->pl = pl; this->pr = pr;
        ncPerBlock = npb; blockNum = bn;
        goGM_.SetGlobalBuffer((__gm__ dataType*)go, (uint64_t)totalNc * outH * outW);
        giGM_.SetGlobalBuffer((__gm__ dataType*)gi, (uint64_t)totalNc * H * W);
        if ASCEND_IS_AIV InitBufs();
    }

    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            int ci = AscendC::GetBlockIdx();
            for (int li = 0; li < ncPerBlock; ++li) {
                int nc = ci * ncPerBlock + li;
                if (nc >= totalNc) break;
                RunNc(nc);
            }
        }
    }

private:
    __aicore__ inline void InitBufs() {
        pipe.InitBuffer(giQ_, BUFFER_NUM, W * sizeof(dataType));
        // goQ_ must hold largest segment: max(W, pl, pr) = max(W, outW) = outW
        pipe.InitBuffer(goQ_, BUFFER_NUM, outW * sizeof(dataType));
        pipe.InitBuffer(giOQ_, BUFFER_NUM, W * sizeof(dataType));
        pipe.InitBuffer(goFB_, outW * sizeof(float));
        pipe.InitBuffer(accB_, W * sizeof(float));
    }

    __aicore__ inline uint64_t goOff(uint64_t nc, int32_t oh) {
        return nc * (uint64_t)outH * outW + (uint64_t)oh * outW;
    }
    __aicore__ inline uint64_t giOff(uint64_t nc, int32_t h) {
        return nc * (uint64_t)H * W + (uint64_t)h * W;
    }

    // ---------- Input / Output helpers ----------
    __aicore__ inline void CopyInGi(uint64_t nc, int32_t h) {
        giT_ = giQ_.AllocTensor<dataType>();
        GmLoadUb(giT_, giGM_[giOff(nc, h)], (uint32_t)W);
        giQ_.EnQue(giT_);
    }

    __aicore__ inline void CopyOutGi(uint64_t nc, int32_t h) {
        giOT_ = giOQ_.DeQue<dataType>();
        UbStoreGm(giGM_[giOff(nc, h)], giOT_, (uint32_t)W);
        giOQ_.FreeTensor(giOT_);
    }

    // ---------- Accumulator management ----------
    __aicore__ inline void ZeroAcc() {
        acc_ = accB_.Get<float>();
        giT_ = giQ_.DeQue<dataType>();
        if constexpr (std::is_same_v<dataType, float>) {
            AscendC::DataCopyParams cp{1, (uint16_t)W, 0, 0};
            AscendC::DataCopy(acc_, giT_, cp);
        } else {
            AscendC::Cast(acc_, giT_, AscendC::RoundMode::CAST_NONE, W);
            AscendC::PipeBarrier<PIPE_V>();
        }
        AscendC::Duplicate(acc_, 0.0f, W);
        giQ_.FreeTensor(giT_);
        AscendC::PipeBarrier<PIPE_ALL>();
    }

    __aicore__ inline void FlushAcc() {
        giOT_ = giOQ_.AllocTensor<dataType>();
        if constexpr (!std::is_same_v<dataType, float>) {
            AscendC::Cast(giOT_, acc_, AscendC::RoundMode::CAST_NONE, W);
        } else {
            AscendC::DataCopyParams cp{1, (uint16_t)W, 0, 0};
            AscendC::DataCopy(giOT_, acc_, cp);
        }
        AscendC::PipeBarrier<PIPE_V>();
        giOQ_.EnQue(giOT_);
    }

    // ---------- Cast loaded data to float32 ----------
    __aicore__ inline void PrepGoF32(int32_t count) {
        if constexpr (std::is_same_v<dataType, float>) {
            goF32_ = goT_.template ReinterpretCast<float>();
        } else {
            goF32_ = goFB_.Get<float>();
            AscendC::Cast(goF32_, goT_, AscendC::RoundMode::CAST_NONE, count);
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    // ---------- Accumulate one contributing output row ----------
    __aicore__ inline void AccRow(uint64_t nc, int32_t oh) {
        // (a) Interior section: load goGM[nc,oh][pl : pl+W] directly
        goT_ = goQ_.AllocTensor<dataType>();
        GmLoadUb(goT_, goGM_[goOff(nc, oh) + pl], (uint32_t)W);
        goQ_.EnQue(goT_);
        goT_ = goQ_.DeQue<dataType>();
        PrepGoF32(W);
        AscendC::PipeBarrier<PIPE_ALL>();
        AscendC::Add(acc_, acc_, goF32_, W);
        goQ_.FreeTensor(goT_);
        AscendC::PipeBarrier<PIPE_ALL>();

        // (b) Left reflection: load goGM[nc,oh][0 : pl], reversed
        if (pl > 0) {
            goT_ = goQ_.AllocTensor<dataType>();
            GmLoadUb(goT_, goGM_[goOff(nc, oh)], (uint32_t)pl);
            goQ_.EnQue(goT_);
            goT_ = goQ_.DeQue<dataType>();
            PrepGoF32(pl);
            AscendC::PipeBarrier<PIPE_ALL>();
            // Left reflect: go_out[ow] corresponds to input[pl-ow] for ow in [0,pl)
            // So for input w_in where 1 <= w_in <= pl: add go_out[pl - w_in]
            for (int w_in = 1; w_in <= pl && w_in < W; ++w_in) {
                int ow = pl - w_in;
                float val = goF32_.GetValue(ow);
                float cur = acc_.GetValue(w_in);
                acc_.SetValue(w_in, cur + val);
            }
            goQ_.FreeTensor(goT_);
            AscendC::PipeBarrier<PIPE_ALL>();
        }

        // (c) Right reflection: load goGM[nc,oh][pl+W : outW], reversed
        if (pr > 0) {
            goT_ = goQ_.AllocTensor<dataType>();
            GmLoadUb(goT_, goGM_[goOff(nc, oh) + pl + W], (uint32_t)pr);
            goQ_.EnQue(goT_);
            goT_ = goQ_.DeQue<dataType>();
            PrepGoF32(pr);
            AscendC::PipeBarrier<PIPE_ALL>();
            // Right reflect: go_out[ow] → input[2*W+pl-ow-2] for ow in [pl+W,pl+W+pr)
            // Pad index pad_idx = ow - (pl+W) in [0, pr)
            // input w_in = 2*W+pl-(pl+W+pad_idx)-2 = W-pad_idx-2
            // For pad_idx in [0, pr): w_in = W-pad_idx-2 ∈ [W-pr-2, W-2]
            // acc[w_in] += goPadF32[pad_idx]
            for (int pad_idx = 0; pad_idx < pr; ++pad_idx) {
                int w_in = W - pad_idx - 2;
                if (w_in >= 0 && w_in < W) {
                    float val = goF32_.GetValue(pad_idx);
                    float cur = acc_.GetValue(w_in);
                    acc_.SetValue(w_in, cur + val);
                }
            }
            goQ_.FreeTensor(goT_);
            AscendC::PipeBarrier<PIPE_ALL>();
        }
    }

    // ---------- Process one input row ----------
    __aicore__ inline void ProcRow(uint64_t nc, int32_t h) {
        CopyInGi(nc, h);
        ZeroAcc();

        // Direct contribution: output row oh = h + pt
        AccRow(nc, h + pt);

        // Top reflection: input row h (< pt) receives from output row pt-h-1
        if (h < pt) {
            AccRow(nc, pt - h - 1);
        }

        // Bottom reflection: input row h (>= H-pb) receives from output row
        // oh = 2*H + pt - h - 2  (reflect formula for bottom pad)
        if (h >= H - pb) {
            AccRow(nc, 2 * H + pt - h - 2);
        }

        FlushAcc();
        CopyOutGi(nc, h);
    }

    __aicore__ inline void RunNc(int32_t nc) {
        uint64_t n64 = (uint64_t)nc;
        for (int h = 0; h < H; ++h) {
            ProcRow(n64, h);
        }
    }

private:
    int32_t totalNc = 0, H = 0, W = 0, outH = 0, outW = 0;
    int32_t pt = 0, pb = 0, pl = 0, pr = 0;
    int32_t ncPerBlock = 0, blockNum = 0;
    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> goGM_, giGM_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> giQ_, goQ_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> giOQ_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> goFB_, accB_;
    AscendC::LocalTensor<dataType> giT_, goT_, giOT_;
    AscendC::LocalTensor<float> acc_, goF32_;
};

// =========================== Entry ======================================
extern "C" __global__ __aicore__ void pad_v4_grad(
    GM_ADDR go, GM_ADDR gi,
    int32_t tnc, int32_t H, int32_t W, int32_t oH, int32_t oW,
    int32_t pt, int32_t pb, int32_t pl, int32_t pr,
    int32_t bn, int32_t npb, int64_t df)
{
    if (df == 0) {
        PadV4GradKernel<float> k;
        k.Init(go, gi, tnc, H, W, oH, oW, pt, pb, pl, pr, bn, npb);
        k.Process();
    } else if (df == 1) {
        PadV4GradKernel<half> k;
        k.Init(go, gi, tnc, H, W, oH, oW, pt, pb, pl, pr, bn, npb);
        k.Process();
    } else {
        PadV4GradKernel<bfloat16_t> k;
        k.Init(go, gi, tnc, H, W, oH, oW, pt, pb, pl, pr, bn, npb);
        k.Process();
    }
}
