134	    // ---------- Accumulate one contributing output row ----------
135	    __aicore__ inline void AccRow(uint64_t nc, int32_t oh) {
136	        // (a) Interior section: load goGM[nc,oh][pl : pl+W] directly
137	        goT_ = goQ_.AllocTensor<dataType>();
138	        GmLoadUb(goT_, goGM_[goOff(nc, oh) + pl], (uint32_t)W);
139	        goQ_.EnQue(goT_);
140	        goT_ = goQ_.DeQue<dataType>();
141	        PrepGoF32(W);
142	        AscendC::PipeBarrier<PIPE_ALL>();
143	        AscendC::Add(acc_, acc_, goF32_, W);
144	        goQ_.FreeTensor(goT_);
145	        AscendC::PipeBarrier<PIPE_ALL>();
146	
147	        // (b) Left reflection: load goGM[nc,oh][0 : pl], reversed
148	        if (pl > 0) {
149	            goT_ = goQ_.AllocTensor<dataType>();
150	            GmLoadUb(goT_, goGM_[goOff(nc, oh)], (uint32_t)pl);
151	            goQ_.EnQue(goT_);
152	            goT_ = goQ_.DeQue<dataType>();
153	            PrepGoF32(pl);
154	            AscendC::PipeBarrier<PIPE_ALL>();
155	            // Left reflect: go_out[ow] corresponds to input[pl-ow] for ow in [0,pl)
156	            // So for input w_in where 1 <= w_in <= pl: add go_out[pl - w_in]
157	            for (int w_in = 1; w_in <= pl && w_in < W; ++w_in) {
158	                int ow = pl - w_in;
159	                float val = goF32_.GetValue(ow);
160	                float cur = acc_.GetValue(w_in);
161	                acc_.SetValue(w_in, cur + val);
162	            }
163	            goQ_.FreeTensor(goT_);
164	            AscendC::PipeBarrier<PIPE_ALL>();
165	        }
166	
167	        // (c) Right reflection: load goGM[nc,oh][pl+W : outW], reversed
168	        if (pr > 0) {
169	            goT_ = goQ_.AllocTensor<dataType>();
170	            GmLoadUb(goT_, goGM_[goOff(nc, oh) + pl + W], (uint32_t)pr);
171	            goQ_.EnQue(goT_);
172	            goT_ = goQ_.DeQue<dataType>();
173	            PrepGoF32(pr);
174	            AscendC::PipeBarrier<PIPE_ALL>();
175	            // Right reflect: go_out[ow] → input[2*W+pl-ow-2] for ow in [pl+W,pl+W+pr)
176	            // Pad index pad_idx = ow - (pl+W) in [0, pr)
177	            // input w_in = 2*W+pl-(pl+W+pad_idx)-2 = W-pad_idx-2
178	            // For pad_idx in [0, pr): w_in = W-pad_idx-2 ∈ [W-pr-2, W-2]
179	            // acc[w_in] += goPadF32[pad_idx]
180	            for (int pad_idx = 0; pad_idx < pr; ++pad_idx) {
181	                int w_in = W - pad_idx - 2;
182	                if (w_in >= 0 && w_in < W) {
183	                    float val = goF32_.GetValue(pad_idx);
184	                    float cur = acc_.GetValue(w_in);
185	                    acc_.SetValue(w_in, cur + val);
186	                }
187	            }
188	            goQ_.FreeTensor(goT_);
189	            AscendC::PipeBarrier<PIPE_ALL>();
190	        }
191	    }
