193	    // ---------- Process one input row ----------
194	    __aicore__ inline void ProcRow(uint64_t nc, int32_t h) {
195	        CopyInGi(nc, h);
196	        ZeroAcc();
197	
198	        // Direct contribution: output row oh = h + pt
199	        AccRow(nc, h + pt);
200	
201	        // Top reflection: input row h (1..pt) receives from output row pt-h
202	        // Forward: output[oh] = input[pt - oh] for oh in [0, pt)
203	        // Backward: input[h] += grad_output[pt - h] for h in [1, pt]
204	        if (h >= 1 && h <= pt) {
205	            AccRow(nc, pt - h);
206	        }
207	
208	        // Bottom reflection: input row h (H-1-pb .. H-2) receives from
209	        // output row oh = 2*H + pt - h - 2
210	        // Forward: output[oh] = input[2*H + pt - oh - 2] for oh in [pt+H, pt+H+pb)
211	        if (h >= H - 1 - pb && h <= H - 2) {
212	            AccRow(nc, 2 * H + pt - h - 2);
213	        }
214	
215	        FlushAcc();
216	        CopyOutGi(nc, h);
217	    }
